import os
import asyncio, websockets, json

def stream_chunks(payload, config=None):
    config = config or {}
    async def _stream():
        uri = f"wss://api.deepgram.com/v1/listen?model={config.get('model', 'nova-2')}&language={config.get('language', 'en')}&encoding={config.get('encoding', 'linear16')}&sample_rate={config.get('sample_rate', 16000)}"
        headers = {"Authorization": f"Token {os.environ.get('DEEPGRAM_API_KEY')}"}
        async with websockets.connect(uri, additional_headers=headers) as ws:
            transcripts = []
            async for chunk in payload:
                await ws.send(chunk)
                resp = json.loads(await ws.recv())
                if resp.get("is_final"):
                    alt = resp.get("channel", {}).get("alternatives", [{}])[0]
                    transcript = alt.get("transcript", "")
                    if transcript:
                        transcripts.append(transcript)
            try:
                while True:
                    resp = json.loads(await asyncio.wait_for(ws.recv(), timeout=1.0))
                    if resp.get("is_final"):
                        alt = resp.get("channel", {}).get("alternatives", [{}])[0]
                        transcript = alt.get("transcript", "")
                        if transcript:
                            transcripts.append(transcript)
                    if resp.get("speech_final"):
                        break
            except asyncio.TimeoutError:
                pass
            return " ".join(transcripts)
    result = asyncio.run(_stream())
    return result
